'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge=(x,k='')=>`<span class="badge ${k}">${esc(x)}</span>`;
function refs(d){return `<ul class="evidence-links">${d.evidence.map(e=>`<li><strong>${esc(e.filename)}</strong><span>${esc(e.documentType)} · source ${esc(e.sourceId)} · ${esc(e.locator)} · ${esc(e.checksumReference)}</span></li>`).join('')}</ul>`}
function preview(d){let sentences=d.outcome.split(/(?<=[.!?])\s+/);let sentence=sentences.slice(0,2).join(' ')||d.outcome;return sentence.length>175?sentence.slice(0,172)+'…':sentence}
function card(d,review){let state=badge(d.resolutionStatus,d.resolutionStatus==='unresolved'?'warn':'ok')+badge('confidence: '+d.confidence,d.confidence==='low'?'warn':'');let operationalPreview=!review&&d.reviewTier==='operational'?`<p class="decision-preview"><strong>Determination:</strong> ${esc(preview(d))}</p>`:'';return `<details class="decision-card" id="decision-${d.id}" data-status="${d.resolutionStatus}" data-confidence="${d.confidence}" data-tier="${d.reviewTier}" data-search="${esc((d.id+' '+d.question+' '+d.outcome+' '+(d.studentReasoning||'')).toLowerCase())}"><summary><span class="decision-number">${d.id}</span><span class="decision-title">${esc(d.question)}${operationalPreview}<span class="badges">${state}${d.disagreement?badge('A/B difference','accent'):''}</span></span><span class="expand">+</span></summary><div class="decision-body">${review?`<div class="compare"><section><h4>Position A</h4><p>${esc(d.aPosition||'Not separately recorded.')}</p></section><section><h4>Position B</h4><p>${esc(d.bPosition||'Not separately recorded.')}</p></section></div><div class="guided"><h4>Guided confirmation</h4><p>${esc(d.guidedConfirmation||'No separate guided confirmation recorded.')}</p><p class="secondary">${esc(d.guidedStatus||'Recorded in the completed final package.')}</p></div><div class="student-reasoning"><h4>Student's spoken reasoning (English translation)</h4><p>${esc(d.studentReasoning||'No separate personal reasoning was recorded.')}</p><p class="secondary">This is a faithful translation of the student's guided spoken response; it is not an independent source reread or a no-AI review claim.</p></div>`:''}<div class="current"><h4>Recorded determination</h4><p>${esc(d.outcome)}</p></div>${d.statementEffect?`<p class="basis"><strong>Statement effect:</strong> ${esc(JSON.stringify(d.statementEffect))}</p>`:''}<h4>Evidence references</h4>${refs(d)}</div></details>`}
function head(id,k,t,d=''){return `<div class="section-heading" id="${id}"><p class="eyebrow">${esc(k)}</p><h2>${esc(t)}</h2>${d?`<p>${esc(d)}</p>`:''}</div>`}
function explorer(ds,review){return `<section>${head('explorer','Decision explorer',review?'All 25 material judgments':'All 100 decisions',review?'Filter by unresolved status, low confidence, or a decision ID.':'The searchable register remains below the concise report summary.')}<div class="filters"><label>Search the register<input id="search" type="search" placeholder="D075, inventory, or owner"></label><label>Show<select id="filter"><option value="all">All decisions</option><option value="material_judgment">Material judgments</option><option value="unresolved">Unresolved</option><option value="low">Low confidence</option></select></label><p id="result-count" aria-live="polite"></p></div><div id="decision-list">${ds.map(d=>card(d,review)).join('')}</div><p id="empty" hidden>No matching decisions.</p></section>`}
function detailTable(rows){return `<div class="table-scroll"><table><thead><tr><th>Line item</th><th>Amount / result</th><th>Qualification</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function scenario(x){return `<section id="selected-scenario">${head('selected-scenario-heading','Selected scenario','Selected provisional case assumptions','This is a transparent selected scenario from the completed case package. It is not final, audited, or independently verified.')}<div class="scenario-note"><p><strong>How to read this scenario:</strong> candidate inputs are adopted only where stated below. Unknown evidence is not converted into a final fact or a balancing entry.</p>${detailTable(x.scenario.assumptions)}</div><div class="scenario-statements">${x.scenario.statements.map(s=>`<article><h3>${esc(s.title)}</h3><p class="secondary">Full selected-scenario table — visible by default.</p>${detailTable(s.rows)}</article>`).join('')}</div><div class="scenario-uncertainties"><h3>Visible uncertainties and sensitivities</h3><ul>${x.scenario.uncertainties.map(u=>`<li>${esc(u)}</li>`).join('')}</ul></div></section>`}
function financial(x){return `<section>${head('statements','Financial reporting','Preliminary statements and schedules','All detail is retained from the completed package. Each section is collapsed by default.')}<div class="financial-details"><h3>Financial schedules</h3>${x.financial.schedules.map(s=>`<details class="document-card"><summary><span>${esc(s.title)}</span><span aria-hidden="true">+</span></summary><div class="document-body">${detailTable(s.rows)}</div></details>`).join('')}<h3 id="detailed-statements">Detailed statements</h3>${x.financial.statements.map(s=>`<details class="document-card"><summary><span>${esc(s.title)} · PRELIMINARY / QUALIFIED</span><span aria-hidden="true">+</span></summary><div class="document-body">${detailTable(s.rows)}</div></details>`).join('')}<h3 id="reconciliations">Reconciliation details</h3>${x.financial.reconciliations.map(r=>`<details class="document-card"><summary><span>${esc(r.id)} · ${esc(r.status)}</span><span aria-hidden="true">+</span></summary><div class="document-body"><p><strong>Calculation / result:</strong> ${esc(r.calculation)}</p><p><strong>Applicable scope:</strong> ${esc(r.scope)}</p><p><strong>Unresolved limitation:</strong> ${esc(r.limitation)}</p></div></details>`).join('')}</div></section>`}
function appendix(x){return `<section>${head('appendix','Audit appendix','Methodology and submission structure','Traceability metadata only: no direct external links, raw source documents, raw register, audit files, hashes, or schema downloads.')}<details class="document-card"><summary>Evidence index</summary><div class="document-body">${x.evidence.map(e=>`<p><strong>${esc(e.filename)}</strong><br>${esc(e.documentType)} · ${esc(e.checksumReference)}</p>`).join('')}</div></details><details class="document-card"><summary>Methodology and submission structure</summary><div class="document-body">${x.methodology.map(e=>`<p><strong>${esc(e.filename)}</strong><br>${esc(e.documentType)} · ${esc(e.checksumReference)}</p>`).join('')}</div></details><details class="document-card"><summary>Final package validation</summary><div class="document-body"><p><strong>submission.json</strong> · schema valid · ${x.validation.errorCount} errors</p><p>${esc(x.case.displayDisclosure)}</p></div></details></section>`}
function render(x){const review=location.pathname.replace(/\/$/,'')==='/review',ds=review?x.decisions.filter(d=>d.reviewTier==='material_judgment'):x.decisions;$('#sidebar').innerHTML=`<a class="brand" href="/"><span class="brand-mark">DPI</span><span>${esc(x.case.id)}<small>AUDIT REPORT</small></span></a><div class="route-switch"><a href="/" ${!review?'aria-current="page"':''}>Report</a><a href="/review/" ${review?'aria-current="page"':''}>Review trail</a></div><nav><a href="#top">Overview</a>${review?'':'<a href="#statements">Financial reporting</a><a href="#board">Board recommendation</a>'}<a href="#explorer">Decision explorer</a><a href="#appendix">Audit appendix</a></nav><div class="sidebar-foot"><span class="local-dot"></span> Published project site<p>Final package validated<br>Public site deployment</p></div>`;let h=`<header id="top"><p class="eyebrow">${esc(x.case.company)} · ${esc(x.case.id)}</p><h1>${review?'Guided Review Trail':'Audit report<br>and decision brief'}</h1><p class="lead">${review?'Twenty-five material judgments with A/B positions, guided confirmation, disagreements, confidence, unresolved status, and statement effect.':x.case.period+' · '+x.case.currency+' · reporting scope: final-package display'}</p><div class="qualification"><strong>${x.case.status}</strong><p>${review?x.case.guidedDisclosure:'This qualification applies to the final outcome; the selected provisional scenario is shown below. '+x.case.displayDisclosure}</p></div></header>`;
if(!review)h+=`<div class="metrics"><div><span>€65,000</span><p>Provisional net profit</p></div><div><span>€125,000</span><p>Provisional equity</p></div><div><span>€60,000</span><p>Closing cash</p></div><div class="warning-metric"><span>€9,000</span><p>Inventory sensitivity</p></div></div><section>${head('conclusion','Executive conclusion','Qualified result','Final amounts remain qualified; selected provisional scenario shown below.')}</section>${scenario(x)}${financial(x)}<section>${head('board','Board recommendation','Decision requested',x.boardRecommendation)}</section><section>${head('featured','Priority judgments','Material, low-confidence, and unresolved first','These decisions are most relevant to the qualified conclusion.')}<div>${x.decisions.filter(d=>x.featuredIds.includes(d.id)).map(d=>card(d,false)).join('')}</div></section>`;h+=explorer(ds,review)+appendix(x)+`<footer>DPI-HT-01 audit report · ${esc(x.case.id)} · completed package displayed with qualifications retained</footer>`;$('#main').innerHTML=h;const cs=[...$('#decision-list').querySelectorAll('.decision-card')];function f(){let q=$('#search').value.toLowerCase(),v=$('#filter').value,n=0;cs.forEach(c=>{let ok=c.dataset.search.includes(q)&&(v==='all'||c.dataset.status===v||c.dataset.confidence===v||c.dataset.tier===v);c.hidden=!ok;n+=ok});$('#result-count').textContent=`Showing ${n} of ${cs.length}`;$('#empty').hidden=!!n}$('#search').oninput=f;$('#filter').onchange=f;f()}
fetch('/site-data.json').then(r=>r.json()).then(render).catch(e=>$('#main').innerHTML=`<div class="error"><h1>Unable to load report data</h1><p>${esc(e.message)}</p></div>`);
